import { useEffect, useState, useCallback, useMemo } from 'react';
import axios from 'axios';
import AddProductModal from './components/AddProductModal';
import EditProductModal from './components/EditProductModal';
import DetailsModal from './components/DetailsModal';
import SendModal from './components/SendModal';
import ConfirmModal from './components/ConfirmModal';
import LoginPage from './components/LoginPage';
import EmailHistoryPage from './components/EmailHistoryPage';
import KeyIssuerPage from './components/KeyIssuerPage';
import { filterListingsByText } from './utils/filterListings';
import './styles/global.css';

const IconEdit = () => (
  <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7" />
    <path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z" />
  </svg>
);

const IconEye = () => (
  <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z" />
    <circle cx="12" cy="12" r="3" />
  </svg>
);

const IconPlus = () => (
  <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round">
    <line x1="12" y1="5" x2="12" y2="19" /><line x1="5" y1="12" x2="19" y2="12" />
  </svg>
);

const IconSend = () => (
  <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <line x1="22" y1="2" x2="11" y2="13" />
    <polygon points="22 2 15 22 11 13 2 9 22 2" />
  </svg>
);

const IconTrash = () => (
  <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <polyline points="3 6 5 6 21 6" />
    <path d="M19 6l-2 14a2 2 0 0 1-2 2H9a2 2 0 0 1-2-2L5 6" />
    <path d="M10 11v6M14 11v6" />
    <path d="M9 6V4a2 2 0 0 1 2-2h2a2 2 0 0 1 2 2v2" />
  </svg>
);

const SENT_EMAIL_MESSAGE =
  'Hi Boss, the email has been sent successfully. You may download the file from your inbox, or please check your spam/junk folder if it is not there.';

const IconCopy = () => (
  <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <rect x="9" y="9" width="13" height="13" rx="2" ry="2" />
    <path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1" />
  </svg>
);

const IconMenu = () => (
  <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
    <line x1="3" y1="6" x2="21" y2="6" />
    <line x1="3" y1="12" x2="21" y2="12" />
    <line x1="3" y1="18" x2="21" y2="18" />
  </svg>
);

export default function App() {
  const [user, setUser] = useState(() => {
    try {
      const raw = localStorage.getItem('vl_user');
      return raw ? JSON.parse(raw) : null;
    } catch {
      return null;
    }
  });

  if (!user) {
    return (
      <LoginPage
        onLoggedIn={(u) => {
          localStorage.setItem('vl_user', JSON.stringify(u));
          setUser(u);
        }}
      />
    );
  }

  return <MainApp user={user} onLogout={() => { localStorage.removeItem('vl_user'); setUser(null); }} />;
}

function MainApp({ user, onLogout }) {
  const [listings, setListings] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchText, setSearchText] = useState('');
  const [activePage, setActivePage] = useState('virtual-listing');
  const [sidebarCollapsed, setSidebarCollapsed] = useState(true);
  const [selectedIds, setSelectedIds] = useState(new Set());
  const [currentPage, setCurrentPage] = useState(1);
  const [toast, setToast] = useState(null);

  const [showAdd, setShowAdd] = useState(false);
  const [showSend, setShowSend] = useState(false);
  const [editItem, setEditItem] = useState(null);
  const [detailItem, setDetailItem] = useState(null);
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
  const [deleting, setDeleting] = useState(false);

  const fetchListings = useCallback(async () => {
    try {
      const { data } = await axios.get('/api/listings');
      setListings(data);
    } catch {
      showToast('Failed to load listings.', 'error');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { fetchListings(); }, [fetchListings]);

  const showToast = (message, type = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3500);
  };

  const toggleSelect = (id) => {
    setSelectedIds((prev) => {
      const next = new Set(prev);
      next.has(id) ? next.delete(id) : next.add(id);
      return next;
    });
  };

  const filteredListings = useMemo(
    () => filterListingsByText(listings, searchText),
    [listings, searchText]
  );

  const ITEMS_PER_PAGE = 25;
  const totalPages = Math.max(1, Math.ceil(filteredListings.length / ITEMS_PER_PAGE));
  const paginatedListings = filteredListings.slice(
    (currentPage - 1) * ITEMS_PER_PAGE,
    currentPage * ITEMS_PER_PAGE
  );

  useEffect(() => { setCurrentPage(1); }, [searchText]);

  const toggleSelectAll = () => {
    const pageIds = paginatedListings.map((l) => l.id);
    if (pageIds.length === 0) return;
    if (pageIds.every((id) => selectedIds.has(id))) {
      setSelectedIds((prev) => {
        const next = new Set(prev);
        pageIds.forEach((id) => next.delete(id));
        return next;
      });
    } else {
      setSelectedIds((prev) => new Set([...prev, ...pageIds]));
    }
  };

  const handleAdded = (listing) => {
    setListings((prev) => [listing, ...prev]);
    setShowAdd(false);
    showToast(`"${listing.product_name}" added successfully.`);
  };

  const handleUpdated = (listing) => {
    setListings((prev) => prev.map((l) => (l.id === listing.id ? listing : l)));
    setEditItem(null);
    showToast(`"${listing.product_name}" updated successfully.`);
  };

  const handleSent = async () => {
    setShowSend(false);
    setSelectedIds(new Set());
    try {
      await navigator.clipboard.writeText(SENT_EMAIL_MESSAGE);
      showToast('Email sent successfully. Message copied to clipboard.');
    } catch {
      showToast('Email sent successfully.');
    }
  };

  const handleCopyMessage = async () => {
    try {
      await navigator.clipboard.writeText(SENT_EMAIL_MESSAGE);
      showToast('Message copied to clipboard.');
    } catch {
      showToast('Failed to copy message.', 'error');
    }
  };

  const confirmDeleteSelected = async () => {
    const ids = Array.from(selectedIds);
    if (ids.length === 0) return;
    setDeleting(true);
    try {
      const results = await Promise.allSettled(
        ids.map((id) => axios.delete(`/api/listings/${id}`))
      );
      const deletedIds = new Set();
      results.forEach((r, i) => {
        if (r.status === 'fulfilled') deletedIds.add(ids[i]);
      });
      const failed = ids.length - deletedIds.size;

      setListings((prev) => prev.filter((l) => !deletedIds.has(l.id)));
      setSelectedIds(new Set());
      setShowDeleteConfirm(false);

      if (failed === 0) {
        showToast(`Deleted ${deletedIds.size} item${deletedIds.size !== 1 ? 's' : ''}.`);
      } else {
        showToast(`Deleted ${deletedIds.size}, ${failed} failed.`, 'error');
      }
    } catch {
      showToast('Failed to delete selected items.', 'error');
    } finally {
      setDeleting(false);
    }
  };

  const selectedNames = listings
    .filter((l) => selectedIds.has(l.id))
    .map((l) => l.product_name);

  const allSelected = paginatedListings.length > 0 && paginatedListings.every((l) => selectedIds.has(l.id));
  const someSelected = selectedIds.size > 0;
  const hasSearch = searchText.trim().length > 0;

  return (
    <div className="app-shell">
      {!sidebarCollapsed && (
        <div className="sidebar-backdrop" onClick={() => setSidebarCollapsed(true)} />
      )}
      <aside className={`sidebar${sidebarCollapsed ? ' collapsed' : ''}`}>
        <div className="sidebar-brand">
          <img src="/logo.jpeg" alt="WYR" />
          <span className="sidebar-label">WYR</span>
          <button
            className="sidebar-toggle"
            type="button"
            onClick={() => setSidebarCollapsed((prev) => !prev)}
            aria-label={sidebarCollapsed ? 'Expand menu' : 'Collapse menu'}
            title={sidebarCollapsed ? 'Expand menu' : 'Collapse menu'}
          >
            {sidebarCollapsed ? '›' : '‹'}
          </button>
        </div>
        <nav className="sidebar-nav">
          <button
            className={activePage === 'virtual-listing' ? 'active' : ''}
            onClick={() => { setActivePage('virtual-listing'); setSidebarCollapsed(true); }}
            title="Virtual Listing"
          >
            <span className="sidebar-icon">VL</span>
            <span className="sidebar-label">Virtual Listing</span>
          </button>
          <button
            className={activePage === 'email-history' ? 'active' : ''}
            onClick={() => { setActivePage('email-history'); setSidebarCollapsed(true); }}
            title="Email History"
          >
            <span className="sidebar-icon">EH</span>
            <span className="sidebar-label">Email History</span>
          </button>
          <button
            className={activePage === 'key-issuer' ? 'active' : ''}
            onClick={() => { setActivePage('key-issuer'); setSidebarCollapsed(true); }}
            title="Key Issuer"
          >
            <span className="sidebar-icon">KI</span>
            <span className="sidebar-label">Key Issuer</span>
          </button>
        </nav>
      </aside>

      <main className="app-container">
        <div className="header">
          <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
            <button
              className="icon-btn mobile-menu-btn"
              onClick={() => setSidebarCollapsed(false)}
              aria-label="Open menu"
            >
              <IconMenu />
            </button>
            <h1>
              {activePage === 'virtual-listing'
                ? 'Virtual Listing'
                : activePage === 'email-history'
                ? 'Email History'
                : 'Key Issuer'}
            </h1>
          </div>
          <div className="header-actions">
            <span style={{ fontSize: '0.85rem', color: '#64748b' }}>Hi, {user.username}</span>
            <button
              className="btn btn-secondary"
              onClick={onLogout}
              style={{ padding: '6px 12px', fontSize: '0.8rem' }}
            >
              Logout
            </button>
            {activePage === 'virtual-listing' && someSelected && (
              <>
                <button className="btn btn-send" onClick={() => setShowSend(true)}>
                  <IconSend />
                  To Send ({selectedIds.size})
                </button>
                <button className="btn btn-danger" onClick={() => setShowDeleteConfirm(true)}>
                  <IconTrash />
                  Delete ({selectedIds.size})
                </button>
              </>
            )}
            {activePage === 'virtual-listing' && (
              <button className="btn btn-secondary" onClick={handleCopyMessage}>
                <IconCopy />
                Copy
              </button>
            )}
            {activePage === 'virtual-listing' && (
              <button className="btn btn-primary" onClick={() => setShowAdd(true)}>
                <IconPlus />
                Add Product
              </button>
            )}
          </div>
        </div>

        {activePage === 'key-issuer' ? (
          <KeyIssuerPage user={user} showToast={showToast} />
        ) : activePage === 'email-history' ? (
          <EmailHistoryPage />
        ) : (
          <>
      {someSelected && (
        <div className="selection-bar">
          {selectedIds.size} item{selectedIds.size !== 1 ? 's' : ''} selected
          <button
            style={{ background: 'none', border: 'none', cursor: 'pointer', color: '#6366f1', fontSize: '0.85rem', textDecoration: 'underline', padding: 0 }}
            onClick={() => setSelectedIds(new Set())}
          >
            Clear selection
          </button>
        </div>
      )}

      <div className="listing-toolbar">
        <label className="search-field">
          <span>Search listings</span>
          <input
            type="search"
            value={searchText}
            onChange={(e) => setSearchText(e.target.value)}
            placeholder="Search by product name or SKU"
          />
        </label>
      </div>

      <div className="table-wrapper">
        {loading ? (
          <div style={{ padding: '48px', textAlign: 'center', color: '#94a3b8' }}>
            Loading…
          </div>
        ) : (
          <table>
            <thead>
              <tr>
                <th style={{ width: 40 }}>
                  <input
                    type="checkbox"
                    checked={allSelected}
                    onChange={toggleSelectAll}
                    title={allSelected ? 'Deselect all' : 'Select all'}
                  />
                </th>
                <th>SKU</th>
                <th>Product Name</th>
                <th className="col-hide-mobile">Product Format</th>
                <th className="col-hide-mobile">URL Link</th>
                <th className="col-hide-mobile">Size</th>
                <th>Created Date</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {paginatedListings.length === 0 ? (
                <tr className="empty-row">
                  <td colSpan={8}>
                    {hasSearch ? 'No listings match your search.' : 'No listings yet. Click "Add Product" to get started.'}
                  </td>
                </tr>
              ) : (
                paginatedListings.map((l) => (
                  <tr key={l.id} className={selectedIds.has(l.id) ? 'selected' : ''}>
                    <td>
                      <input
                        type="checkbox"
                        checked={selectedIds.has(l.id)}
                        onChange={() => toggleSelect(l.id)}
                      />
                    </td>
                    <td>{l.sku}</td>
                    <td style={{ fontWeight: 500 }}>{l.product_name}</td>
                    <td className="col-hide-mobile">{l.product_format ?? '—'}</td>
                    <td className="cell-link col-hide-mobile">
                      {l.url_link ? (
                        <a href={l.url_link} target="_blank" rel="noreferrer" title={l.url_link}>
                          {l.url_link}
                        </a>
                      ) : '—'}
                    </td>
                    <td className="col-hide-mobile">{l.size ?? '—'}</td>
                    <td style={{ whiteSpace: 'nowrap' }}>
                      {new Date(l.created_date).toLocaleDateString()}
                    </td>
                    <td>
                      <div className="actions-cell">
                        <button
                          className="icon-btn edit"
                          title="Edit"
                          onClick={() => setEditItem(l)}
                        >
                          <IconEdit />
                        </button>
                        <button
                          className="icon-btn view"
                          title="View Details"
                          onClick={() => setDetailItem(l)}
                        >
                          <IconEye />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        )}
      </div>

      {filteredListings.length > 0 && (
        <div className="pagination">
          <span className="pagination-info">
            {filteredListings.length === 0 ? '0' : (currentPage - 1) * ITEMS_PER_PAGE + 1}–
            {Math.min(currentPage * ITEMS_PER_PAGE, filteredListings.length)} of {filteredListings.length} items
          </span>
          <div className="pagination-controls">
            <button
              className="page-btn"
              disabled={currentPage === 1}
              onClick={() => setCurrentPage(1)}
              aria-label="First page"
            >«</button>
            <button
              className="page-btn"
              disabled={currentPage === 1}
              onClick={() => setCurrentPage((p) => p - 1)}
              aria-label="Previous page"
            >‹</button>
            {Array.from({ length: totalPages }, (_, i) => i + 1)
              .filter((p) => p === 1 || p === totalPages || Math.abs(p - currentPage) <= 1)
              .reduce((acc, p, idx, arr) => {
                if (idx > 0 && p - arr[idx - 1] > 1) acc.push('...');
                acc.push(p);
                return acc;
              }, [])
              .map((p, i) =>
                p === '...' ? (
                  <span key={`ellipsis-${i}`} className="page-ellipsis">…</span>
                ) : (
                  <button
                    key={p}
                    className={`page-btn${p === currentPage ? ' active' : ''}`}
                    onClick={() => setCurrentPage(p)}
                  >{p}</button>
                )
              )}
            <button
              className="page-btn"
              disabled={currentPage === totalPages}
              onClick={() => setCurrentPage((p) => p + 1)}
              aria-label="Next page"
            >›</button>
            <button
              className="page-btn"
              disabled={currentPage === totalPages}
              onClick={() => setCurrentPage(totalPages)}
              aria-label="Last page"
            >»</button>
          </div>
        </div>
      )}

      {showAdd && (
        <AddProductModal onClose={() => setShowAdd(false)} onAdded={handleAdded} />
      )}
      {editItem && (
        <EditProductModal
          listing={editItem}
          onClose={() => setEditItem(null)}
          onUpdated={handleUpdated}
        />
      )}
      {detailItem && (
        <DetailsModal listing={detailItem} onClose={() => setDetailItem(null)} />
      )}
      {showSend && (
        <SendModal
          selectedIds={Array.from(selectedIds)}
          onClose={() => setShowSend(false)}
          onSent={handleSent}
        />
      )}
      {showDeleteConfirm && (
        <ConfirmModal
          title={`Delete ${selectedIds.size} item${selectedIds.size !== 1 ? 's' : ''}?`}
          confirmLabel="Delete"
          variant="danger"
          busy={deleting}
          onCancel={() => !deleting && setShowDeleteConfirm(false)}
          onConfirm={confirmDeleteSelected}
          message={
            <>
              <p style={{ margin: 0 }}>
                You're about to permanently delete the following
                {selectedIds.size !== 1 ? ' items' : ' item'}:
              </p>
              <ul style={{ margin: '8px 0 0', paddingLeft: 20, color: '#475569', maxHeight: 160, overflowY: 'auto' }}>
                {selectedNames.slice(0, 10).map((n, i) => (
                  <li key={i} style={{ marginBottom: 2 }}>{n}</li>
                ))}
                {selectedNames.length > 10 && (
                  <li style={{ color: '#94a3b8' }}>…and {selectedNames.length - 10} more</li>
                )}
              </ul>
              <p style={{ margin: '12px 0 0', color: '#b91c1c', fontSize: '0.88rem' }}>
                The database entries and their S3 files will be removed. This cannot be undone.
              </p>
            </>
          }
        />
      )}

      {toast && (
        <div className={`toast ${toast.type}`}>{toast.message}</div>
      )}
          </>
        )}
      </main>
    </div>
  );
}

import { useCallback, useEffect, useRef, useState } from 'react';
import axios from 'axios';
import { formatSingaporeDateTime } from '../utils/dateTime';

const DEFAULT_EXPIRY_YEARS = 50;

// Today + DEFAULT_EXPIRY_YEARS as yyyyMMdd (Feb 29 rolls to Mar 1 in non-leap years)
function defaultExpiryDate() {
  const d = new Date();
  d.setFullYear(d.getFullYear() + DEFAULT_EXPIRY_YEARS);
  const mm = String(d.getMonth() + 1).padStart(2, '0');
  const dd = String(d.getDate()).padStart(2, '0');
  return `${d.getFullYear()}${mm}${dd}`;
}

function createInitialForm() {
  return {
    company: '',
    invoice: '',
    hardwareId: '',
    expiryDate: defaultExpiryDate(),
  };
}

const IconCalendar = () => (
  <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <rect x="3" y="4" width="18" height="18" rx="2" ry="2" />
    <line x1="16" y1="2" x2="16" y2="6" />
    <line x1="8" y1="2" x2="8" y2="6" />
    <line x1="3" y1="10" x2="21" y2="10" />
  </svg>
);

const IconCopy = () => (
  <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <rect x="9" y="9" width="13" height="13" rx="2" ry="2" />
    <path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1" />
  </svg>
);

// yyyyMMdd <-> yyyy-MM-dd (the format <input type="date"> requires)
function yyyymmddToDateInput(value) {
  if (!/^\d{8}$/.test(value)) return '';
  return `${value.slice(0, 4)}-${value.slice(4, 6)}-${value.slice(6, 8)}`;
}

function dateInputToYyyymmdd(value) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return '';
  return value.replaceAll('-', '');
}

export default function KeyIssuerPage({ user, showToast }) {
  const dateInputRef = useRef(null);
  const openDatePicker = () => {
    try {
      dateInputRef.current?.showPicker?.();
    } catch {
      // showPicker() isn't supported in every browser (e.g. Safari/Firefox) — the
      // calendar icon button still opens it directly via its own native input.
    }
  };

  const [form, setForm] = useState(createInitialForm);
  const [generating, setGenerating] = useState(false);
  const [formError, setFormError] = useState('');
  const [lastIssued, setLastIssued] = useState(null);

  const [keys, setKeys] = useState([]);
  const [loading, setLoading] = useState(true);
  const [listError, setListError] = useState('');
  const [companyFilter, setCompanyFilter] = useState('');
  const [invoiceFilter, setInvoiceFilter] = useState('');

  const fetchKeys = useCallback(async (company = '', invoice = '') => {
    setLoading(true);
    setListError('');
    try {
      const { data } = await axios.get('/api/key-issuer', {
        params: { company, invoice },
      });
      setKeys(data);
    } catch {
      setListError('Failed to load issued keys.');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchKeys();
  }, [fetchKeys]);

  const handleSearch = (e) => {
    e.preventDefault();
    fetchKeys(companyFilter, invoiceFilter);
  };

  const handleClearSearch = () => {
    setCompanyFilter('');
    setInvoiceFilter('');
    fetchKeys();
  };

  const validateForm = () => {
    if (!form.company.trim() || !form.invoice.trim()) {
      return 'Company and Invoice No are required.';
    }
    if (!/^\d{8}$/.test(form.expiryDate)) {
      return 'Expiry Date must be 8 digits in yyyyMMdd format.';
    }
    if (!/^[0-9a-fA-F]+$/.test(form.hardwareId) || form.hardwareId.length % 2 !== 0) {
      return 'Hardware ID must be a hex string with an even number of characters.';
    }
    return '';
  };

  const handleGenerate = async (e) => {
    e.preventDefault();
    const error = validateForm();
    if (error) {
      setFormError(error);
      return;
    }
    setFormError('');
    setGenerating(true);
    try {
      const { data } = await axios.post('/api/key-issuer/generate', {
        ...form,
        issuedBy: user?.username,
      });
      setLastIssued(data);
      setKeys((prev) => [data, ...prev]);
      setForm(createInitialForm());
    } catch (err) {
      setFormError(err.response?.data?.error ?? 'Failed to generate key.');
    } finally {
      setGenerating(false);
    }
  };

  const handleClear = () => {
    setForm(createInitialForm());
    setFormError('');
    setLastIssued(null);
  };

  const handleDownload = (id) => {
    window.open(`/api/key-issuer/${id}/download`, '_blank');
  };

  const handleCopy = async (outputKey) => {
    try {
      await navigator.clipboard.writeText(outputKey);
      showToast?.('Output key copied to clipboard.');
    } catch {
      showToast?.('Failed to copy output key.', 'error');
    }
  };

  return (
    <>
      <div className="page-heading">
        <div>
          <h2>Key Issuer</h2>
          <p>Generate hardware-locked license keys and review everything issued so far.</p>
        </div>
      </div>

      <div className="table-wrapper" style={{ padding: 20, marginBottom: 20 }}>
        <form onSubmit={handleGenerate} style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
          {formError && (
            <div style={{ color: '#ef4444', fontSize: '0.85rem', background: '#fef2f2', padding: '8px 12px', borderRadius: '8px' }}>
              {formError}
            </div>
          )}

          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: 16 }}>
            <div className="form-group">
              <label>Company *</label>
              <input
                value={form.company}
                onChange={(e) => setForm({ ...form, company: e.target.value })}
                placeholder="e.g. Company ABC"
              />
            </div>
            <div className="form-group">
              <label>Invoice No *</label>
              <input
                value={form.invoice}
                onChange={(e) => setForm({ ...form, invoice: e.target.value })}
                placeholder="e.g. P0001"
              />
            </div>
            <div className="form-group">
              <label>Hardware ID *</label>
              <input
                value={form.hardwareId}
                onChange={(e) => setForm({ ...form, hardwareId: e.target.value.trim() })}
                placeholder="e.g. 10dc297f"
              />
            </div>
            <div className="form-group">
              <label>Expiry Date * <span className="muted-text" style={{ fontWeight: 400 }}>(yyyyMMdd)</span></label>
              <div style={{ display: 'flex', gap: 8 }}>
                <input
                  value={form.expiryDate}
                  onChange={(e) => setForm({ ...form, expiryDate: e.target.value.trim() })}
                  onFocus={openDatePicker}
                  onClick={openDatePicker}
                  placeholder="e.g. 20381111"
                  maxLength={8}
                  style={{ flex: 1 }}
                />
                <div
                  style={{
                    position: 'relative',
                    width: 40,
                    flex: '0 0 40px',
                    border: '1px solid #d1d5db',
                    borderRadius: 8,
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    color: '#64748b',
                    cursor: 'pointer',
                  }}
                  title="Pick a date"
                >
                  <IconCalendar />
                  <input
                    ref={dateInputRef}
                    type="date"
                    value={yyyymmddToDateInput(form.expiryDate)}
                    onChange={(e) => setForm({ ...form, expiryDate: dateInputToYyyymmdd(e.target.value) })}
                    style={{ position: 'absolute', inset: 0, opacity: 0, cursor: 'pointer', width: '100%', height: '100%' }}
                  />
                </div>
              </div>
            </div>
          </div>

          {lastIssued && (
            <div className="form-group">
              <label>Output Key</label>
              <input value={lastIssued.output_key} readOnly style={{ fontFamily: 'monospace' }} />
            </div>
          )}

          <div style={{ display: 'flex', gap: 10 }}>
            <button type="submit" className="btn btn-primary" disabled={generating}>
              {generating ? 'Generating…' : 'Generate'}
            </button>
            {lastIssued && (
              <button
                type="button"
                className="btn btn-secondary"
                onClick={() => handleDownload(lastIssued.id)}
              >
                Download .dc file
              </button>
            )}
            {lastIssued && (
              <button
                type="button"
                className="btn btn-secondary"
                onClick={() => handleCopy(lastIssued.output_key)}
              >
                <IconCopy />
                Copy
              </button>
            )}
            <button type="button" className="btn btn-secondary" onClick={handleClear} disabled={generating}>
              Clear
            </button>
          </div>
        </form>
      </div>

      <form className="listing-toolbar" onSubmit={handleSearch} style={{ gap: 10, justifyContent: 'flex-start', flexWrap: 'wrap' }}>
        <label className="search-field" style={{ width: 220 }}>
          <span>Company</span>
          <input
            value={companyFilter}
            onChange={(e) => setCompanyFilter(e.target.value)}
            placeholder="Filter by company"
          />
        </label>
        <label className="search-field" style={{ width: 220 }}>
          <span>Invoice</span>
          <input
            value={invoiceFilter}
            onChange={(e) => setInvoiceFilter(e.target.value)}
            placeholder="Filter by invoice"
          />
        </label>
        <div style={{ display: 'flex', gap: 8, alignItems: 'flex-end', paddingBottom: 1 }}>
          <button type="submit" className="btn btn-primary" style={{ padding: '9px 16px' }}>Search</button>
          <button type="button" className="btn btn-secondary" style={{ padding: '9px 16px' }} onClick={handleClearSearch}>
            Reset
          </button>
        </div>
      </form>

      <div className="table-wrapper">
        {loading ? (
          <div style={{ padding: '48px', textAlign: 'center', color: '#94a3b8' }}>Loading…</div>
        ) : listError ? (
          <div style={{ padding: '24px', color: '#ef4444' }}>{listError}</div>
        ) : (
          <table>
            <thead>
              <tr>
                <th>Company</th>
                <th>Invoice</th>
                <th>Hardware ID</th>
                <th>Expiry Date</th>
                <th>Output Key</th>
                <th>Issued By</th>
                <th>Issued At</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {keys.length === 0 ? (
                <tr className="empty-row">
                  <td colSpan={8}>No keys issued yet.</td>
                </tr>
              ) : (
                keys.map((k) => (
                  <tr key={k.id}>
                    <td>{k.company}</td>
                    <td>{k.invoice}</td>
                    <td>{k.hardware_id}</td>
                    <td>{k.expiry_date}</td>
                    <td style={{ fontFamily: 'monospace' }}>{k.output_key}</td>
                    <td>{k.issued_by ?? '—'}</td>
                    <td style={{ whiteSpace: 'nowrap' }}>{formatSingaporeDateTime(k.issued_at)}</td>
                    <td>
                      <button
                        className="btn btn-secondary"
                        style={{ padding: '6px 12px', fontSize: '0.8rem' }}
                        onClick={() => handleDownload(k.id)}
                      >
                        Download
                      </button>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        )}
      </div>
    </>
  );
}

import { useEffect, useState, useCallback, useMemo } from 'react';
